322→func TestHandleLifecycleCompaction_PreservesTranscriptOffset(t *testing.T) {
323→	// Cannot use t.Parallel() because we use t.Chdir()
324→	tmpDir := t.TempDir()
325→	t.Chdir(tmpDir)
326→
327→	// Initialize git repo with a commit (not empty)
328→	setupGitRepoWithCommit(t, tmpDir)
329→	paths.ClearWorktreeRootCache()
330→
331→	// Create .entire directory structure
332→	if err := os.MkdirAll(paths.EntireDir, 0o755); err != nil {
333→		t.Fatalf("Failed to create .entire: %v", err)
334→	}
335→
336→	// Create a transcript file
337→	transcriptPath := filepath.Join(tmpDir, "transcript.jsonl")
338→	transcriptContent := `{"type":"user","message":{"role":"user","content":"test prompt"}}` + "\n"
339→	if err := os.WriteFile(transcriptPath, []byte(transcriptContent), 0o644); err != nil {
340→		t.Fatalf("Failed to create transcript: %v", err)
341→	}
342→
343→	sessionID := "compaction-test-session"
344→
345→	// Create session state with non-zero transcript offset (set by prior condensation)
346→	sessionState := &strategy.SessionState{
347→		SessionID:                 sessionID,
348→		StartedAt:                 time.Now(),
349→		CheckpointTranscriptStart: 50,
350→	}
351→	if err := strategy.SaveSessionState(context.Background(), sessionState); err != nil {
352→		t.Fatalf("Failed to save session state: %v", err)
353→	}
354→
355→	ag := newMockAgent()
356→	event := &agent.Event{
357→		Type:       agent.Compaction,
358→		SessionID:  sessionID,
359→		SessionRef: transcriptPath,
360→	}
361→
362→	// Compaction should NOT reset the transcript offset.
363→	// Many agents (e.g., Gemini) fire pre-compress as a no-op after every tool call;
364→	// resetting the offset causes stale files to re-appear in carry-forward.
365→	err := handleLifecycleCompaction(context.Background(), ag, event)
366→	if err != nil {
367→		t.Logf("handleLifecycleCompaction returned error (expected in minimal test): %v", err)
368→	}
369→
370→	// Verify CheckpointTranscriptStart was preserved (not reset to 0)
371→	loadedState, loadErr := strategy.LoadSessionState(context.Background(), sessionID)
372→	if loadErr != nil {
373→		t.Fatalf("Failed to load session state after compaction: %v", loadErr)
374→	}
375→	if loadedState == nil {
376→		t.Fatal("Session state is nil after compaction")
377→	}
378→	if loadedState.CheckpointTranscriptStart != 50 {
379→		t.Errorf("CheckpointTranscriptStart = %d, want 50 (compaction should preserve offset)",
380→			loadedState.CheckpointTranscriptStart)
381→	}
382→}
