539→// ReadAgentTypeFromTree reads the agent type from a checkpoint's metadata.json file in a git tree.
540→// If metadata.json doesn't exist (shadow branches), it falls back to detecting the agent
541→// from the presence of agent-specific config files (.gemini/settings.json or .claude/).
542→// Returns agent.AgentTypeUnknown if the agent type cannot be determined.
543→func ReadAgentTypeFromTree(tree *object.Tree, checkpointPath string) types.AgentType {
544→	// First, try to read from metadata.json (present in condensed/committed checkpoints)
545→	metadataPath := checkpointPath + "/" + paths.MetadataFileName
546→	if file, err := tree.File(metadataPath); err == nil {
547→		if content, err := file.Contents(); err == nil {
548→			var metadata checkpoint.CommittedMetadata
549→			if err := json.Unmarshal([]byte(content), &metadata); err == nil && metadata.Agent != "" {
550→				return metadata.Agent
551→			}
552→		}
553→	}
554→
555→	// Fall back to detecting agent from config files (shadow branches don't have metadata.json).
556→	// Order: Gemini (most specific check), Claude (established default), OpenCode (newest/preview).
557→	if _, err := tree.File(".gemini/settings.json"); err == nil {
558→		return agent.AgentTypeGemini
559→	}
560→	if _, err := tree.Tree(".claude"); err == nil {
561→		return agent.AgentTypeClaudeCode
562→	}
563→	// OpenCode: .opencode directory or opencode.json config
564→	if _, err := tree.Tree(".opencode"); err == nil {
565→		return agent.AgentTypeOpenCode
566→	}
567→	if _, err := tree.File("opencode.json"); err == nil {
568→		return agent.AgentTypeOpenCode
569→	}
570→
571→	return agent.AgentTypeUnknown
572→}
